/** Shared Lucene 5.3 ranking rules for the offline search reader. */
final class OfflineSearchRanking {
 static String script(){return "function offlineRankRows(rows,kind,terms,mode,sortOrder,rawQuery){\n if(!rows.length)return Promise.resolve(rows);\n return json(BASE+'topics/ranking.json').then(function(ranking){\n  var phrase=mode==='phrase',unique=uniqueList(terms),prefix=kind==='root'?'R|':kind==='partial'?'P|':'F|',queryKeys=(phrase?terms:unique).map(function(t){return prefix+t}),keys=queryKeys.slice();\n  if(phrase&&kind==='partial'&&terms.length>1){keys=[];terms.forEach(function(t,i){if(i)keys.push('P|__WS__');keys.push('P|'+t)})}\n  if(phrase&&kind!=='partial')keys=uniqueList(keys);\n  var loadKeys=uniqueList(keys);\n  return Promise.all(loadKeys.map(function(k){return loadDocs(kind,k)})).then(function(parts){\n   var metas={},frequencies={};parts.forEach(function(p,i){var k=loadKeys[i],map={};metas[k]=p.m;p.list.forEach(function(row){map[row[0]]=row[1]});frequencies[k]=map});\n   var floatSlot=typeof Float32Array==='function'?new Float32Array(1):null;function f(n){if(typeof Math.fround==='function')return Math.fround(n);if(floatSlot){floatSlot[0]=n;return floatSlot[0]}return n}\n   function idf(k){var m=metas[k];return f(1+Math.log(ranking.maxDoc/((m?m.df:0)+1)))}\n   var idfSum=0,squares=0;keys.forEach(function(k){var v=idf(k);idfSum=f(idfSum+v);squares=f(squares+f(v*v))});\n   var queryNorm=f(1/Math.sqrt(squares)),normSlot=kind==='root'?2:kind==='partial'?1:0;\n   rows.forEach(function(row){var d=ranking.docs[row.doc];if(!d)throw Error('Missing ranking metadata for '+row.doc);var norm=d.n[normSlot],count=row.occurrences===undefined?row.score:row.occurrences,score=0,matched=0;\n    if(phrase)score=f(f(Math.sqrt(count))*f(idfSum*norm));\n    else{keys.forEach(function(k){var tf=frequencies[k][row.doc]||0,v=idf(k);if(tf){matched++;var weight=f(f(v*queryNorm)*v);score=f(score+f(f(Math.sqrt(tf))*f(weight*norm)))}});score=f(score*f(matched/keys.length))}\n    row.occurrences=count;row.score=score;row.postid=d.p;row.whole_word_match=false;\n   });\n   if(kind!=='partial'||sortOrder==='date_newest'||sortOrder==='date_oldest')return rows;\n   var wholeTerms=words(rawQuery,true),wholeKind=ranking.wholeKind;\n   if(!wholeKind||!wholeTerms.length)return rows;\n   return Promise.all((phrase?wholeTerms:uniqueList(wholeTerms)).map(function(t){return phrase?loadPositions(wholeKind,'F|'+t):loadDocs(wholeKind,'F|'+t)})).then(function(all){\n    var usable=[];for(var i=0;i<all.length;i++){if(all[i].m)usable.push(all[i]);else if(mode!=='any')return rows}\n    if(!usable.length)return rows;var whole=phrase?combinePhrase(usable,wholeTerms):combineDocs(usable,mode),found={};whole.forEach(function(h){found[h.doc]=true});rows.forEach(function(h){h.whole_word_match=!!found[h.doc]});return rows;\n   });\n  });\n });\n}\nfunction offlinePostIdOrder(a,b){var x=String(a.postid||'0').replace(/^0+/,''),y=String(b.postid||'0').replace(/^0+/,'');if(/^\\d*$/.test(x)&&/^\\d*$/.test(y))return y.length-x.length||(x<y?1:x>y?-1:0);return x<y?1:x>y?-1:0}\nfunction offlineRankCompare(a,b,sortOrder){\n if(sortOrder!=='date_newest'&&sortOrder!=='date_oldest'&&!!a.whole_word_match!==!!b.whole_word_match)return a.whole_word_match?-1:1;\n if(sortOrder==='occurrences'){var n=b.occurrences-a.occurrences;if(n)return n}\n return (b.score||0)-(a.score||0)||(sortOrder==='relevance'?a.doc-b.doc:offlinePostIdOrder(a,b));\n}\n\nfunction offlineDateSort(rows,order,dates){return rows.slice().sort(function(a,b){var x=+dates[a.doc]||0,y=+dates[b.doc]||0;if(!x&&y)return 1;if(x&&!y)return -1;return (order==='date_newest'?-1:1)*(x-y)||offlineRankCompare(a,b,order)})}\n";}
}
